#[derive(PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct GeomOp {
    pub geoms: Vec<Geom>,
    pub op: Fn_,
    pub predicate: Predicate,
}

impl GeomOp {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsGeomOp<'a>> {
        use crate::types::generated::graph_generated::GeomOpBuilder as FbsGeomOpBuilder;

        let mut geoms_offsets = Vec::with_capacity(self.geoms.len());
        for val in self.geoms.iter() {
            let offset = val.serialize_to(builder);
            geoms_offsets.push(offset);
        }
        let geoms_offset = builder.create_vector(&geoms_offsets);

        let mut bldr = FbsGeomOpBuilder::new(builder);
        bldr.add_geoms(geoms_offset);
        bldr.add_op(FbsFn::from(self.op));
        bldr.add_predicate(FbsPredicate::from(self.predicate));
        bldr.finish()
    }
}

impl From<FbsGeomOp<'_>> for GeomOp {
    fn from(fbs: FbsGeomOp<'_>) -> Self {
        let mut geoms = Vec::new();
        for elem in fbs.geoms() {
            geoms.push(elem.into());
        }

        let op = Fn_::from(fbs.op());
        let predicate = Predicate::from(fbs.predicate());
        Self {
            geoms,
            op,
            predicate,
        }
    }
}

impl crate::FbsSerde for GeomOp {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsGeomOp>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

impl Default for GeomOp {
    fn default() -> Self {
        Self {
            geoms: Vec::<Geom>::default(),
            op: Fn_::None_,
            predicate: Predicate::location,
        }
    }
}

