#[derive(Clone, Debug, PartialEq, Hash, Eq, Serialize, Deserialize)]
pub enum QueryPathElementUnion {
    NodeQuery(NodeQuery),
    EdgeQuery(EdgeQuery),
}

impl Default for QueryPathElementUnion {
    fn default() -> Self {
        Self::NodeQuery(NodeQuery::default())
    }
}

impl QueryPathElementUnion {
    pub fn serialize_to(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder,
    ) -> (WIPOffset<UnionWIPOffset>, FbsQueryPathElementUnion) {
        match self {
            Self::NodeQuery(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsQueryPathElementUnion::NodeQuery;
                (offset, ty)
            }
            Self::EdgeQuery(val) => {
                let offset = val.serialize_to(builder).as_union_value();
                let ty = FbsQueryPathElementUnion::EdgeQuery;
                (offset, ty)
            }
        }
    }
}

