/// The GraphQuery encapsulates the entire world graph query.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct GraphQuery {
    pub limit: u32,
    pub order_by: Option<Vec<OrderBy>>,
    pub path: Vec<QueryPathElement>,
}

impl GraphQuery {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsGraphQuery<'a>> {
        use crate::types::generated::graph_generated::GraphQueryBuilder as FbsGraphQueryBuilder;

        let order_by_offset = self.order_by.as_ref().map(|v| {
            let mut order_by_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                order_by_offsets.push(offset);
            }
            let order_by_offset = builder.create_vector(&order_by_offsets);
            order_by_offset
        });
        let mut path_offsets = Vec::with_capacity(self.path.len());
        for val in self.path.iter() {
            let offset = val.serialize_to(builder);
            path_offsets.push(offset);
        }
        let path_offset = builder.create_vector(&path_offsets);

        let mut bldr = FbsGraphQueryBuilder::new(builder);
        bldr.add_limit(self.limit);
        if let Some(offset) = order_by_offset {
            bldr.add_order_by(offset);
        }
        bldr.add_path(path_offset);
        bldr.finish()
    }
}

impl From<FbsGraphQuery<'_>> for GraphQuery {
    fn from(fbs: FbsGraphQuery<'_>) -> Self {
        let limit = fbs.limit();
        let order_by = if let Some(val) = fbs.order_by() {
            let mut order_by = Vec::new();
            for elem in val {
                order_by.push(elem.into());
            }

            Some(order_by)
        } else {
            None
        };

        let mut path = Vec::new();
        for elem in fbs.path() {
            path.push(elem.into());
        }

        Self {
            limit,
            order_by,
            path,
        }
    }
}

impl crate::FbsSerde for GraphQuery {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsGraphQuery>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct NodeIdPair {
    pub node_id: GraphNodeId,
    pub stream_id: Option<ObjectId>,
}

impl NodeIdPair {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsNodeIdPair<'a>> {
        use crate::types::generated::graph_generated::NodeIdPairBuilder as FbsNodeIdPairBuilder;

        let node_id_offset = self.node_id.serialize_to(builder);
        let stream_id_offset = self.stream_id.as_ref().map(|o| o.serialize_to(builder));

        let mut bldr = FbsNodeIdPairBuilder::new(builder);
        bldr.add_node_id(node_id_offset);
        if let Some(offset) = stream_id_offset {
            bldr.add_stream_id(offset);
        }
        bldr.finish()
    }
}

impl From<FbsNodeIdPair<'_>> for NodeIdPair {
    fn from(fbs: FbsNodeIdPair<'_>) -> Self {
        let node_id = GraphNodeId::from(fbs.node_id());
        let stream_id = fbs.stream_id().map(ObjectId::from);
        Self { node_id, stream_id }
    }
}

impl crate::FbsSerde for NodeIdPair {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsNodeIdPair>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct NodeList {
    pub nodes: Vec<GraphNode>,
}

impl NodeList {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsNodeList<'a>> {
        use crate::types::generated::graph_generated::NodeListBuilder as FbsNodeListBuilder;

        let mut nodes_offsets = Vec::with_capacity(self.nodes.len());
        for val in self.nodes.iter() {
            let offset = val.serialize_to(builder);
            nodes_offsets.push(offset);
        }
        let nodes_offset = builder.create_vector(&nodes_offsets);

        let mut bldr = FbsNodeListBuilder::new(builder);
        bldr.add_nodes(nodes_offset);
        bldr.finish()
    }
}

impl From<FbsNodeList<'_>> for NodeList {
    fn from(fbs: FbsNodeList<'_>) -> Self {
        let mut nodes = Vec::new();
        for elem in fbs.nodes() {
            nodes.push(elem.into());
        }

        Self { nodes }
    }
}

impl crate::FbsSerde for NodeList {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsNodeList>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

